    nid.hWnd = GetConsoleWindow();
    nid.uID = 1;
    nid.uFlags = NIF_ICON | NIF_MESSAGE | NIF_TIP;
    nid.hIcon = LoadIcon(NULL, IDI_APPLICATION);
